CREATE TABLE IF NOT EXISTS property_state_history(id CHAR(36) PRIMARY KEY,property_id CHAR(36) NOT NULL,from_status VARCHAR(30) NOT NULL,to_status VARCHAR(30) NOT NULL,reason VARCHAR(255) NOT NULL,actor_id CHAR(36),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_property_history(property_id,created_at));
CREATE TABLE IF NOT EXISTS lease_occupants(id CHAR(36) PRIMARY KEY,lease_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,phone VARCHAR(40),identity_no VARCHAR(80),is_primary BOOLEAN NOT NULL DEFAULT FALSE,INDEX idx_lease_occupants(lease_id));
CREATE TABLE IF NOT EXISTS lease_state_history(id CHAR(36) PRIMARY KEY,lease_id CHAR(36) NOT NULL,from_status VARCHAR(30) NOT NULL,to_status VARCHAR(30) NOT NULL,reason VARCHAR(255) NOT NULL,actor_id CHAR(36),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_lease_history(lease_id,created_at));
CREATE TABLE IF NOT EXISTS bill_adjustments(id CHAR(36) PRIMARY KEY,bill_id CHAR(36) NOT NULL,kind VARCHAR(30) NOT NULL,amount BIGINT NOT NULL,reason VARCHAR(255) NOT NULL,actor_id CHAR(36),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_bill_adjustments(bill_id,created_at));
CREATE TABLE IF NOT EXISTS payment_receipts(id CHAR(36) PRIMARY KEY,reference VARCHAR(120) NOT NULL UNIQUE,amount BIGINT NOT NULL,payer VARCHAR(120) NOT NULL,paid_at TIMESTAMP NOT NULL,status VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS payment_allocations(id CHAR(36) PRIMARY KEY,payment_id CHAR(36) NOT NULL,bill_id CHAR(36) NOT NULL,amount BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(payment_id,bill_id),INDEX idx_allocation_bill(bill_id));
CREATE TABLE IF NOT EXISTS work_order_materials(id CHAR(36) PRIMARY KEY,work_order_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,quantity BIGINT NOT NULL,unit_cost BIGINT NOT NULL,INDEX idx_work_material(work_order_id));
CREATE TABLE IF NOT EXISTS work_order_state_history(id CHAR(36) PRIMARY KEY,work_order_id CHAR(36) NOT NULL,from_status VARCHAR(30) NOT NULL,to_status VARCHAR(30) NOT NULL,reason VARCHAR(255) NOT NULL,actor_id CHAR(36),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_work_history(work_order_id,created_at));
CREATE TABLE IF NOT EXISTS settlement_items(id CHAR(36) PRIMARY KEY,settlement_id CHAR(36) NOT NULL,kind VARCHAR(40) NOT NULL,description VARCHAR(255) NOT NULL,amount BIGINT NOT NULL,INDEX idx_settlement_items(settlement_id));
CREATE TABLE IF NOT EXISTS idempotency_keys(scope VARCHAR(80) NOT NULL,request_key VARCHAR(160) NOT NULL,resource_id CHAR(36) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(scope,request_key));
